-- Generated by schema.py (SQLite / PostgreSQL compatible)

CREATE TABLE LoanProduct (
  product_id VARCHAR(255) NOT NULL,
  product_name VARCHAR(255) NOT NULL,
  min_principal NUMERIC(16,2) NOT NULL,
  max_principal NUMERIC(16,2) NOT NULL,
  min_term_months INTEGER NOT NULL,
  max_term_months INTEGER NOT NULL,
  annual_rate_pct NUMERIC(16,2) NOT NULL,
  max_dti_pct NUMERIC(16,2) NOT NULL,
  min_credit_score INTEGER NOT NULL,
  min_disposable_income NUMERIC(16,2) NOT NULL,
  effective_from DATE NOT NULL,
  effective_to DATE,
  status VARCHAR(255) NOT NULL CHECK (status IN ('ACTIVE', 'RETIRED')),
  PRIMARY KEY (product_id)
);

CREATE TABLE Applicant (
  applicant_id VARCHAR(255) NOT NULL,
  full_name VARCHAR(255) NOT NULL,
  date_of_birth DATE NOT NULL,
  gender VARCHAR(255) NOT NULL CHECK (gender IN ('F', 'M', 'X')),
  marital_status VARCHAR(255) NOT NULL CHECK (marital_status IN ('SINGLE', 'MARRIED', 'DIVORCED', 'WIDOWED')),
  region_code VARCHAR(255) NOT NULL,
  customer_since DATE NOT NULL,
  PRIMARY KEY (applicant_id)
);

CREATE TABLE Employment (
  employment_id VARCHAR(255) NOT NULL,
  applicant_id VARCHAR(255) NOT NULL,
  employer_name VARCHAR(255) NOT NULL,
  employment_type VARCHAR(255) NOT NULL CHECK (employment_type IN ('SALARIED', 'SELF_EMPLOYED', 'CONTRACT')),
  start_date DATE NOT NULL,
  end_date DATE,
  is_current BOOLEAN NOT NULL,
  PRIMARY KEY (employment_id),
  FOREIGN KEY (applicant_id) REFERENCES Applicant(applicant_id)
);

CREATE TABLE IncomeRecord (
  income_id VARCHAR(255) NOT NULL,
  applicant_id VARCHAR(255) NOT NULL,
  employment_id VARCHAR(255),
  source VARCHAR(255) NOT NULL CHECK (source IN ('PAYSLIP', 'BANK_STATEMENT', 'TAX_RETURN', 'DECLARED')),
  monthly_income NUMERIC(16,2) NOT NULL,
  verification_status VARCHAR(255) NOT NULL CHECK (verification_status IN ('VERIFIED', 'UNVERIFIED')),
  recorded_date DATE NOT NULL,
  PRIMARY KEY (income_id),
  FOREIGN KEY (applicant_id) REFERENCES Applicant(applicant_id),
  FOREIGN KEY (employment_id) REFERENCES Employment(employment_id)
);

CREATE TABLE CreditFacility (
  facility_id VARCHAR(255) NOT NULL,
  facility_type VARCHAR(255) NOT NULL CHECK (facility_type IN ('CREDIT_CARD', 'PERSONAL_LOAN', 'AUTO_LOAN', 'HOME_LOAN', 'BNPL')),
  lender_name VARCHAR(255) NOT NULL,
  sanctioned_amount NUMERIC(16,2) NOT NULL,
  outstanding_balance NUMERIC(16,2) NOT NULL,
  monthly_obligation NUMERIC(16,2) NOT NULL,
  max_dpd_12m INTEGER NOT NULL CHECK (max_dpd_12m IN (0, 30, 60, 90)),
  status VARCHAR(255) NOT NULL CHECK (status IN ('ACTIVE', 'CLOSED')),
  opened_date DATE NOT NULL,
  closed_date DATE,
  PRIMARY KEY (facility_id)
);

CREATE TABLE ApplicantFacility (
  applicant_id VARCHAR(255) NOT NULL,
  facility_id VARCHAR(255) NOT NULL,
  role VARCHAR(255) NOT NULL CHECK (role IN ('PRIMARY', 'JOINT')),
  share_pct INTEGER NOT NULL,
  PRIMARY KEY (applicant_id, facility_id),
  FOREIGN KEY (applicant_id) REFERENCES Applicant(applicant_id),
  FOREIGN KEY (facility_id) REFERENCES CreditFacility(facility_id)
);

CREATE TABLE ProductDocumentRequirement (
  product_id VARCHAR(255) NOT NULL,
  document_type VARCHAR(255) NOT NULL CHECK (document_type IN ('ID_PROOF', 'ADDRESS_PROOF', 'INCOME_PROOF', 'VEHICLE_QUOTE', 'CONTRACTOR_QUOTE', 'ADMISSION_LETTER')),
  is_mandatory BOOLEAN NOT NULL,
  PRIMARY KEY (product_id, document_type),
  FOREIGN KEY (product_id) REFERENCES LoanProduct(product_id)
);

CREATE TABLE LoanApplication (
  application_id VARCHAR(255) NOT NULL,
  applicant_id VARCHAR(255) NOT NULL,
  product_id VARCHAR(255) NOT NULL,
  requested_principal NUMERIC(16,2) NOT NULL,
  requested_term_months INTEGER NOT NULL,
  purpose VARCHAR(255) NOT NULL CHECK (purpose IN ('DEBT_CONSOLIDATION', 'MEDICAL', 'TRAVEL', 'WEDDING', 'OTHER_PERSONAL', 'NEW_VEHICLE', 'USED_VEHICLE', 'RENOVATION', 'REPAIR', 'SOLAR_INSTALL', 'TUITION', 'STUDY_ABROAD')),
  channel VARCHAR(255) NOT NULL CHECK (channel IN ('ONLINE', 'BRANCH', 'PARTNER')),
  submitted_at TIMESTAMP NOT NULL,
  status VARCHAR(255) NOT NULL CHECK (status IN ('SUBMITTED', 'UNDER_REVIEW', 'MANUAL_REVIEW', 'APPROVED', 'REJECTED', 'DISBURSED', 'CANCELLED')),
  status_updated_at TIMESTAMP NOT NULL,
  loan_id VARCHAR(255),
  PRIMARY KEY (application_id),
  UNIQUE (loan_id),
  FOREIGN KEY (applicant_id) REFERENCES Applicant(applicant_id),
  FOREIGN KEY (product_id) REFERENCES LoanProduct(product_id)
);

CREATE TABLE Document (
  document_id VARCHAR(255) NOT NULL,
  application_id VARCHAR(255) NOT NULL,
  document_type VARCHAR(255) NOT NULL CHECK (document_type IN ('ID_PROOF', 'ADDRESS_PROOF', 'INCOME_PROOF', 'VEHICLE_QUOTE', 'CONTRACTOR_QUOTE', 'ADMISSION_LETTER')),
  status VARCHAR(255) NOT NULL CHECK (status IN ('VERIFIED', 'MISSING', 'REJECTED')),
  received_at TIMESTAMP,
  status_at TIMESTAMP NOT NULL,
  supersedes_document_id VARCHAR(255),
  PRIMARY KEY (document_id),
  FOREIGN KEY (application_id) REFERENCES LoanApplication(application_id),
  FOREIGN KEY (supersedes_document_id) REFERENCES Document(document_id)
);

CREATE TABLE AffordabilityCheck (
  check_id VARCHAR(255) NOT NULL,
  application_id VARCHAR(255) NOT NULL,
  checked_at TIMESTAMP NOT NULL,
  income_basis VARCHAR(255) NOT NULL CHECK (income_basis IN ('VERIFIED', 'DECLARED_UNVERIFIED')),
  monthly_income_used NUMERIC(16,2) NOT NULL,
  income_source_count INTEGER NOT NULL,
  income_conflict_flag BOOLEAN NOT NULL,
  existing_obligations_monthly NUMERIC(16,2) NOT NULL,
  proposed_installment NUMERIC(16,2) NOT NULL,
  dti_before_pct NUMERIC(16,2) NOT NULL,
  dti_after_pct NUMERIC(16,2) NOT NULL,
  disposable_income_after NUMERIC(16,2) NOT NULL,
  credit_score INTEGER NOT NULL,
  utilisation_pct NUMERIC(16,2),
  max_dpd_12m INTEGER NOT NULL CHECK (max_dpd_12m IN (0, 30, 60, 90)),
  enquiries_180d INTEGER NOT NULL,
  employment_type VARCHAR(255) NOT NULL CHECK (employment_type IN ('SALARIED', 'SELF_EMPLOYED', 'CONTRACT', 'UNEMPLOYED')),
  employment_tenure_months INTEGER NOT NULL,
  docs_complete BOOLEAN NOT NULL,
  rule_version VARCHAR(255) NOT NULL CHECK (rule_version IN ('LT-RULES-1.0')),
  PRIMARY KEY (check_id),
  FOREIGN KEY (application_id) REFERENCES LoanApplication(application_id)
);

CREATE TABLE Decision (
  decision_id VARCHAR(255) NOT NULL,
  application_id VARCHAR(255) NOT NULL,
  check_id VARCHAR(255) NOT NULL,
  decided_at TIMESTAMP NOT NULL,
  decision VARCHAR(255) NOT NULL CHECK (decision IN ('APPROVED', 'REJECTED', 'MANUAL_REVIEW')),
  rule_id VARCHAR(255) NOT NULL CHECK (rule_id IN ('R00_PRODUCT_LIMITS', 'R01_DUPLICATE', 'R02_INCOME_FLOOR', 'R03_HARD_DECLINE', 'R04_MANUAL_REVIEW', 'R05_AUTO_APPROVE', 'R06_ANALYST_APPROVE', 'R07_ANALYST_DECLINE')),
  reason_codes VARCHAR(255) NOT NULL,
  rule_inputs TEXT NOT NULL,
  decided_by VARCHAR(255) NOT NULL,
  supersedes_decision_id VARCHAR(255),
  PRIMARY KEY (decision_id),
  FOREIGN KEY (application_id) REFERENCES LoanApplication(application_id),
  FOREIGN KEY (check_id) REFERENCES AffordabilityCheck(check_id),
  FOREIGN KEY (supersedes_decision_id) REFERENCES Decision(decision_id)
);

CREATE TABLE RepaymentSchedule (
  schedule_id VARCHAR(255) NOT NULL,
  loan_id VARCHAR(255) NOT NULL,
  application_id VARCHAR(255) NOT NULL,
  installment_no INTEGER NOT NULL,
  due_date DATE NOT NULL,
  opening_balance NUMERIC(16,2) NOT NULL,
  principal_due NUMERIC(16,2) NOT NULL,
  interest_due NUMERIC(16,2) NOT NULL,
  total_due NUMERIC(16,2) NOT NULL,
  closing_balance NUMERIC(16,2) NOT NULL,
  status VARCHAR(255) NOT NULL CHECK (status IN ('SCHEDULED', 'PAID', 'OVERDUE', 'CANCELLED')),
  PRIMARY KEY (schedule_id),
  FOREIGN KEY (loan_id) REFERENCES LoanApplication(loan_id),
  FOREIGN KEY (application_id) REFERENCES LoanApplication(application_id)
);

CREATE TABLE Disbursement (
  disbursement_id VARCHAR(255) NOT NULL,
  loan_id VARCHAR(255) NOT NULL,
  application_id VARCHAR(255) NOT NULL,
  eligibility_decision_id VARCHAR(255) NOT NULL,
  amount NUMERIC(16,2) NOT NULL,
  disbursed_at TIMESTAMP NOT NULL,
  status VARCHAR(255) NOT NULL CHECK (status IN ('DISBURSED')),
  PRIMARY KEY (disbursement_id),
  UNIQUE (loan_id),
  FOREIGN KEY (loan_id) REFERENCES LoanApplication(loan_id),
  FOREIGN KEY (application_id) REFERENCES LoanApplication(application_id),
  FOREIGN KEY (eligibility_decision_id) REFERENCES Decision(decision_id)
);

CREATE TABLE ApplicationEvent (
  event_id VARCHAR(255) NOT NULL,
  application_id VARCHAR(255) NOT NULL,
  event_seq INTEGER NOT NULL,
  event_type VARCHAR(255) NOT NULL CHECK (event_type IN ('SUBMITTED', 'REVIEW_STARTED', 'DECISION_MADE', 'MANUAL_REVIEW_RESOLVED', 'DISBURSED', 'CANCELLED')),
  from_status VARCHAR(255) CHECK (from_status IN ('SUBMITTED', 'UNDER_REVIEW', 'MANUAL_REVIEW', 'APPROVED', 'REJECTED', 'DISBURSED', 'CANCELLED')),
  to_status VARCHAR(255) NOT NULL CHECK (to_status IN ('SUBMITTED', 'UNDER_REVIEW', 'MANUAL_REVIEW', 'APPROVED', 'REJECTED', 'DISBURSED', 'CANCELLED')),
  event_ts TIMESTAMP NOT NULL,
  actor VARCHAR(255) NOT NULL,
